import type { Taxonomy } from './module.types';

/** Row in the unit list and in a module's Units table. */
export interface UnitListItem {
   id: string;
   moduleId: string;
   moduleCode: string;
   /** Generated by the backend (PRD A-05), unique within the module. */
   code: string;
   /** Unlock position within the module, starting at 1 (FR-CUR-006). */
   order: number;
   titleEn: string;
   titleMy: string;
   lessonCount: number;
   updatedAt: string;
}

export interface UnitDetail extends UnitListItem {
   descriptionEn: string;
   descriptionMy: string;
   module: {
      id: string;
      code: string;
      titleEn: string;
      level: Taxonomy;
      category: Taxonomy;
   };
}

/** Body of POST /units and PATCH /units/:id (FR-CUR-004). */
export interface UnitPayload {
   moduleId: string;
   titleEn: string;
   titleMy: string;
   descriptionEn: string;
   descriptionMy: string;
}

export interface UnitFilters {
   search?: string;
   moduleId?: string;
   page: number;
}
